struct WidgetFactory {
    virtual ~WidgetFactory() = default;
    virtual std::unique_ptr<Button> make_button() const = 0;
    virtual std::unique_ptr<Slider> make_slider() const = 0;
};

struct DarkTheme final : WidgetFactory {
    std::unique_ptr<Button> make_button() const override { return std::make_unique<DarkButton>(); }
    std::unique_ptr<Slider> make_slider() const override { return std::make_unique<DarkSlider>(); }
};

